class Label(RootModel[str]):
    root: str = Field(
        ..., description='Printable ASCII label for the token list.', max_length=64
    )


class CreateBrowserAccessTokenRequest(BaseModel):
    ttl_seconds: TtlSeconds | None = Field(
        None,
        alias='ttlSeconds',
        description='Life of the token in seconds. Null: valid until the browser stops.',
    )
    label: Label | None = Field(
        None, description='Printable ASCII label for the token list.'
    )
    close_connections_on_expiry: bool | None = Field(
        False,
        alias='closeConnectionsOnExpiry',
        description='Close the open connections of the token when it expires. Else expiry stops only new connections.',
    )


class BrowserAccessTokenCreated(BaseModel):
    id: UUID
    token: str = Field(..., description='Secret token. It appears only in this answer.')
    cdp_url: str = Field(..., alias='cdpUrl', description='CDP URL with this token.')
    live_url: str | None = Field(
        ...,
        alias='liveUrl',
        description='Live view URL with this token; null when the project hides the live view.',
    )
    expires_at: AwareDatetime | None = Field(
        ...,
        alias='expiresAt',
        description='Expiry of the token; null when it is valid until the browser stops.',
    )


class Kind(Enum):
    customer = 'customer'
    viewer = 'viewer'
    system = 'system'


class BrowserAccessTokenItem(BaseModel):
    id: UUID
    label: str
    kind: Kind
    created_at: AwareDatetime = Field(..., alias='createdAt')
    expires_at: AwareDatetime | None = Field(..., alias='expiresAt')
    last_used_at: AwareDatetime | None = Field(
        ..., alias='lastUsedAt', description='Always null for now.'
    )


class BrowserAccessTokenList(BaseModel):
    items: List[BrowserAccessTokenItem]


class BrowserAccessTokenRevoked(BaseModel):
    effective_by: AwareDatetime = Field(
        ..., alias='effectiveBy', description='Latest time when the revoke is complete.'
    )


class Type(Enum):
    api_key = 'api_key'
    user = 'user'
    service = 'service'


class BrowserAccessEventActor(BaseModel):
    type: Type
    id: str | None = Field(..., description='API key ID, user ID, or service name.')
    run_id: UUID | None = Field(..., alias='runId')


class Event(Enum):
    token_created = 'token_created'
    token_revoked = 'token_revoked'
    tokens_revoked = 'tokens_revoked'


class TokenKind(Enum):
    customer = 'customer'
    viewer = 'viewer'
    system = 'system'


class RevokedKind(Enum):
    customer = 'customer'
    viewer = 'viewer'
    system = 'system'


class BrowserAccessEventItem(BaseModel):
    id: UUID
    event: Event
    token_id: str | None = Field(..., alias='tokenId')
    token_kind: TokenKind | None = Field(..., alias='tokenKind')
    revoked_kinds: List[RevokedKind] | None = Field(..., alias='revokedKinds')
    actor: BrowserAccessEventActor
    created_at: AwareDatetime = Field(..., alias='createdAt')


class BrowserAccessEventList(BaseModel):
    items: List[BrowserAccessEventItem]
    total_items: int = Field(..., alias='totalItems')
    page_number: int = Field(..., alias='pageNumber')
    page_size: int = Field(..., alias='pageSize')


class BrowserSessionItemView(BaseModel):
    model_config = ConfigDict(
        regex_engine="python-re",
    )
    solve_captchas: bool | None = Field(
        None, alias='solveCaptchas', description='Effective CAPTCHA solving setting.'
    )
    profile_id: UUID | None = Field(None, alias='profileId')
    id: UUID = Field(..., description='Unique identifier for the session', title='ID')
    status: BrowserSessionStatus = Field(
        ...,
        description='Current status of the session (active/stopped)',
        title='Status',
    )
    live_url: str | None = Field(
        None,
        alias='liveUrl',
        description='URL where the browser can be viewed live in real-time',
        title='Live URL',
    )
    cdp_url: str | None = Field(
        None,
        alias='cdpUrl',
        description='Chrome DevTools Protocol URL for browser automation',
        title='CDP URL',
    )
    timeout_at: AwareDatetime = Field(
        ...,
        alias='timeoutAt',
        description='Timestamp when the session will timeout',
        title='Timeout At',
    )
    started_at: AwareDatetime = Field(
        ...,
        alias='startedAt',
        description='Timestamp when the session was created and started',
        title='Started At',
    )
    finished_at: AwareDatetime | None = Field(
        None,
        alias='finishedAt',
        description='Timestamp when the session was stopped (None if still active)',
        title='Finished At',
    )
    proxy_used_mb: str | None = Field(
        '0',
        alias='proxyUsedMb',
        description='Amount of proxy data used in MB',
        pattern='^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$',
        title='Proxy Used MB',
    )
    proxy_cost: str | None = Field(
        '0',
        alias='proxyCost',
        description='Cost of proxy usage in USD',
        pattern='^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$',
        title='Proxy Cost',
    )
    browser_cost: str | None = Field(
        '0',
        alias='browserCost',
        description='Cost of browser session hosting in USD',
        pattern='^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$',
        title='Browser Cost',
    )
    agent_session_id: UUID | None = Field(
        None,
        alias='agentSessionId',
        description='ID of the agent session that created this browser (None for standalone BaaS sessions)',
        title='Agent Session ID',
    )
    recording_url: str | None = Field(
        None,
        alias='recordingUrl',
        description='Presigned URL to download the session recording. Only populated on `GET /browsers/{session_id}`; always `null` in list responses.',
        title='Recording URL',
    )
    metadata: Dict[str, str] | None = Field(
        {},
        description='Caller-supplied labels set when the browser was created.',
        title='Metadata',
    )
    extensions: List[BrowserExtensionView] | None = Field(
        default_factory=list,
        description='Extensions installed in the browser, in the order of `extensionIds`.',
        title='Extensions',
    )


class BrowserSessionListResponse(BaseModel):
    items: List[BrowserSessionItemView] = Field(
        ...,
        description='List of browser session views for the current page',
        title='Items',
    )
    total_items: int = Field(
        ...,
        alias='totalItems',
        description='Total number of items in the list',
        title='Total Items',
    )
    page_number: int = Field(
        ..., alias='pageNumber', description='Page number', title='Page Number'
    )
    page_size: int = Field(
        ..., alias='pageSize', description='Number of items per page', title='Page Size'
    )


class CreateBrowserSessionRequest(BaseModel):
    profile_id: UUID | None = Field(
        None,
        alias='profileId',
        description='The ID of the profile to use for the session',
        title='Profile ID',
    )
    network_policy_id: UUID | None = Field(
        None,
        alias='networkPolicyId',
        description='ID of a network policy that allows or blocks domains for this browser. Policy changes reach the browser within seconds.',
        title='Networkpolicyid',
    )
    proxy_country_code: ProxyCountryCode | None = Field(
        ProxyCountryCode.us,
        alias='proxyCountryCode',
        description='Country code for proxy location. Defaults to US. Set to null to disable proxy.',
        title='Proxy Country Code',
    )
    metadata: Dict[str, str] | None = Field(
        None,
        description='Labels for this browser. Up to 10 key-value pairs. Filterable on the browsers list and in the dashboard history.',
        title='Metadata',
    )
    timeout: int | None = Field(
        60,
        description='The timeout for the session in minutes. All users can use up to 240 minutes (4 hours). Browser sessions are charged per browser-hour at your account rate.',
        title='Timeout',
    )
    browser_screen_width: BrowserScreenWidth | None = Field(
        None,
        alias='browserScreenWidth',
        description='Custom screen width in pixels for the browser.',
        title='Browser Screen Width',
    )
    browser_screen_height: BrowserScreenHeight | None = Field(
        None,
        alias='browserScreenHeight',
        description='Custom screen height in pixels for the browser.',
        title='Browser Screen Height',
    )
    allow_resizing: bool | None = Field(
        False,
        alias='allowResizing',
        description='Whether to allow the browser to be resized during the session (not recommended since it reduces stealthiness).',
        title='Allow Resizing',
    )
    pdf_renderer_enabled: bool | None = Field(
        True,
        alias='pdfRendererEnabled',
        description="Whether Chrome renders PDFs in a tab. Set to false to stop the in-tab render; the file is saved to the session's download directory either way.",
        title='PDF Renderer Enabled',
    )
    solve_captchas: bool | None = Field(
        True,
        alias='solveCaptchas',
        description='Whether the browser detects and solves CAPTCHAs on its own. Set to false to handle CAPTCHAs yourself. Defaults to true.',
        title='Solve Captchas',
    )
    custom_proxy: CustomProxy | None = Field(
        None,
        alias='customProxy',
        description='Custom proxy settings to use for the session. If not provided, our proxies will be used. Custom proxies are an enterprise feature: contact sales@browser-use.com to enable them.',
        title='Custom Proxy',
    )
    enable_recording: bool | None = Field(
        False,
        alias='enableRecording',
        description='If True, enables session recording. Defaults to False.',
        title='Enable Recording',
    )
    extension_ids: List[UUID] | None = Field(
        [],
        alias='extensionIds',
        description='Up to 3 ready extensions from POST /api/v4/extensions to install before the browser starts.',
        max_length=3,
        title='Extension IDs',
    )
    cdp_token_ttl_seconds: CdpTokenTtlSeconds | None = Field(
        None,
        alias='cdpTokenTtlSeconds',
        description='Life in seconds of the customer token in cdpUrl and liveUrl. Null: valid until the browser stops. The create answers 422 while the feature is off.',
    )
    close_connections_on_expiry: bool | None = Field(
        False,
        alias='closeConnectionsOnExpiry',
        description='Close the open connections of the customer token when it expires. The create answers 422 while the feature is off.',
    )


class ExtensionListResponse(BaseModel):
    items: List[ExtensionView] = Field(..., title='Items')
    total_items: int = Field(
        ...,
        alias='totalItems',
        description='Total number of items in the list',
        title='Total Items',
    )
    page_number: int = Field(
        ..., alias='pageNumber', description='Page number', title='Page Number'
    )
    page_size: int = Field(
        ..., alias='pageSize', description='Number of items per page', title='Page Size'
    )


class HTTPValidationError(BaseModel):
    detail: List[ValidationError] | None = Field(None, title='Detail')


class IntegrationListResponse(BaseModel):
    integrations: List[IntegrationResponse] = Field(..., title='Integrations')
    total: int = Field(..., title='Total')
